use vstd::prelude::*;

verus! {
    // Function to calculate the minimum moves from a to b
    spec fn min_moves(a: nat, b: nat) -> nat
        requires a >= 1 && b >= 1,
    {
        if a == b {
            0
        } else if a < b {
            // To go from a to b, we can only increase
            // The difference must be covered by odd increments
            let diff = b - a;
            (diff + 1) / 2 // Each move can cover at least 1, so we need (diff + 1) / 2 moves
        } else {
            // To go from a to b, we can only decrease
            // The difference must be covered by even decrements
            let diff = a - b;
            (diff + 1) / 2 // Each move can cover at least 2, so we need (diff + 1) / 2 moves
        }
    }

    fn solve(input: Vec<(i8, i8)>) -> Vec<i8>
        requires input.len() > 0,
        ensures result.len() == input.len(),
    {
        let mut result: Vec<i8> = Vec::new();
        for (a, b) in input.iter() {
            let a_nat = *a as nat;
            let b_nat = *b as nat;
            let moves = min_moves(a_nat, b_nat);
            result.push(moves as i8);
        }
        result
    }
}
